def subtract(a, b):
    # Filter out empty intervals (start >= end)
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    if not b:
        return sorted(a)

    # Merge overlapping intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a_merged
    result = []
    for a_start, a_end in a_merged:
        current = a_start
        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is entirely before current position
                continue
            if b_start >= a_end:
                # b interval is entirely after a interval
                break

            # There is overlap
            if current < b_start:
                # Add the part before b starts
                result.append([current, b_start])

            # Move current to after b ends
            current = max(current, b_end)

        # Add remaining part of a interval
        if current < a_end:
            result.append([current, a_end])

    return result

